52	        let edits = undo
53	            .counts
54	            .iter()
55	            .map(|(edit_id, count)| {
56	                sum_tree::Edit::Insert(UndoMapEntry {
57	                    key: UndoMapKey {
58	                        edit_id: *edit_id,
59	                        undo_id: undo.timestamp,
60	                    },
61	                    undo_count: *count,
62	                })
63	            })
64	            .collect::<Vec<_>>();
65	        self.0.edit(edits, ());
66	    }
