69	        self.undo_count(edit_id) % 2 == 1
70	    }
71	    pub fn was_undone(&self, edit_id: clock::Lamport, version: &clock::Global) -> bool {
72	        let mut cursor = self.0.cursor::<UndoMapKey>(());
73	        cursor.seek(
74	            &UndoMapKey {
